var __PAGES = {"index.html":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>HGI Billing sync</title>\n<style>body{font:16px/1.6 system-ui,sans-serif;max-width:620px;margin:0 auto;padding:24px 16px;background:#fff;color:#1c1917}a{color:#c2410c}@media(prefers-color-scheme:dark){body{background:#141210;color:#eee}}</style></head>\n<body><h1>HGI Billing</h1><p>This is the cloud sync service of the HGI Billing Android app by HARIGURU INDUSTRIES.</p>\n<p><a href=\"/privacy\">Privacy policy</a> · <a href=\"/delete-account\">Delete your account</a></p></body></html>\n","privacy.html":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>HGI Billing — Privacy Policy</title><style>body{font:16px/1.6 system-ui,sans-serif;max-width:760px;margin:0 auto;padding:24px 16px;color:#1c1917;background:#fff}\nh1{font-size:1.6rem}h2{font-size:1.15rem;margin-top:1.6em}a{color:#c2410c}@media(prefers-color-scheme:dark){body{background:#141210;color:#eee}a{color:#fb923c}}</style></head>\n<body><h1>Privacy Policy — HGI Billing (Android)</h1><p><em>Last updated: 15 November 2026 — applies from app version 9.4 (username and password accounts, data kept in Google Sheets).</em></p><p>HGI Billing is published by HARIGURU INDUSTRIES, Ahmedabad, Gujarat, India (\"HGI\", \"we\").</p><h2>1. Your account</h2><p>You create an account with a <strong>username and password</strong> of your choice. We store the username, a random account ID, the date the account was created, its status and the time of your last log-in. Your password itself is never stored: we keep only a one-way hash of it (<strong>scrypt</strong> or <strong>PBKDF2-HMAC-SHA256</strong>, depending on the server), made with a random salt and a secret key that exists only on our server. For each device you log in on we keep a session record (a hashed session code, the device model, start and expiry time), so that logging out ends the session on our server too.</p><h2>2. The data you enter</h2><p>You enter business data: company profile (including GSTIN, bank and UPI details), buyers, products and stock, invoices, quotations, credit/debit notes, payments and settings.</p><ul><li>It is stored <strong>on your phone</strong>, so billing works without internet.</li><li>It is also stored in <strong>your HGI cloud account</strong>: a Google Sheets spreadsheet owned by HARIGURU INDUSTRIES and, where HGI offers PDF copies, a private file store (Google Cloud Storage), hosted by Google LLC as our service provider. Every row is marked with your account ID. This lets you log in on any phone and get your data back, and keeps several phones in step.</li><li>Only our sync service can read or write this data, and only for the account that is signed in. Authorised HGI staff can access the cloud data for support or recovery. We do not use your business data for advertising, do not sell it and do not share it with anyone else except where the law requires.</li></ul><h2>3. GSTIN look-up</h2><p>Where HGI's server offers it, when you type a GSTIN for a buyer, the app can fetch that business's registration details (legal and trade name, address, registration status) from GST records. The GSTIN is sent through our server to our authorised GST data provider; nothing else about you or your buyers is sent. Results may be kept for up to 7 days to avoid repeat look-ups.</p><h2>3a. E-invoice (IRN) and e-way bill</h2><p>This section applies only where HGI's server offers e-invoice and e-way bill; the app shows when they are not available. Only when you tap *Generate* (or check a status / cancel), the document's details — your business, the buyer and consignee, items, amounts and transport details — are sent through our server and our GST Suvidha Provider (GSP) to the government's e-invoice (IRP) and e-way bill systems, as the GST law requires. The answer (IRN, acknowledgement, signed QR code, e-way bill number and validity) is stored with the invoice in your account. The e-invoice / e-way bill API user name and password you enter are checked with the government system and kept only on our server, encrypted; they are never stored on the phone or shown again. You can remove them at any time in Settings; deleting your account removes them.</p><h2>3b. PIN codes</h2><p>State, state code and district are found from a PIN code using the India Post PIN directory stored inside the app. No PIN code is sent anywhere for this.</p><h2>4. When data leaves the phone</h2><ul><li>Sync with your HGI cloud account, GSTIN look-ups and e-invoice / e-way bill requests you start, always over encrypted HTTPS.</li><li>When you choose to share a PDF, CSV or backup file (WhatsApp, e-mail, Drive …) or open a link (WhatsApp, UPI payment).</li></ul><p>The app contains no advertising or analytics SDKs. Android's own Google cloud backup of the app is switched off.</p><h2>5. Security</h2><p>Connections are encrypted (HTTPS). The app holds no database or storage keys: only our server (a Google Cloud Run service or a Google Apps Script web app operated by HARIGURU INDUSTRIES) writes to the spreadsheet and file store, and it checks the signed-in account on every request, so an account can only see and change its own rows. The spreadsheet is shared only with HGI staff who administer it; Google encrypts it at rest and keeps its version history. You can also protect the app with a PIN.</p><h2>6. Keeping and deleting your data</h2><p>We keep your cloud data while your account exists. You can delete it at any time:</p><ul><li>in the app: <strong>Settings → Account &amp; sync → Delete account and cloud data</strong>, or</li><li>on the web: the account-deletion page linked from the app's Google Play listing (enter your username and password), or</li><li>by e-mail to <a href=\"mailto:info@hariguru.com.\">info@hariguru.com.</a></li></ul><p>Deletion removes all your rows from the spreadsheet and your PDFs from the file store at once, and ends all your sessions. Earlier versions inside the spreadsheet's version history are kept by Google for a limited time. We keep only the account row marked \"deleted\" (account ID, username, creation and deletion dates — no business data and no password hash) so that phones still logged in to the deleted account stop syncing; the username can then be registered again.</p><h2>7. Children</h2><p>The app is a business tool and is not directed at children.</p><h2>8. Contact</h2><p>HARIGURU INDUSTRIES, Ahmedabad, Gujarat, India · <a href=\"mailto:info@hariguru.com\">info@hariguru.com</a></p><p><a href=\"/delete-account\">Delete your account and cloud data</a></p></body></html>\n","delete-account.html":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>HGI Billing — Delete account</title>\n<style>body{font:16px/1.6 system-ui,sans-serif;max-width:620px;margin:0 auto;padding:24px 16px;color:#1c1917;background:#fff}\nh1{font-size:1.5rem}.box{border:1px solid #e7e5e4;border-radius:12px;padding:16px;margin:16px 0}\nlabel{display:block;margin:10px 0 4px;font-weight:600}input[type=text],input[type=password]{font:inherit;width:100%;box-sizing:border-box;padding:10px 12px;border:1px solid #a8a29e;border-radius:8px;background:transparent;color:inherit}\n.chk{display:flex;gap:8px;align-items:flex-start;font-weight:400}button{font:inherit;padding:10px 16px;border-radius:8px;border:0;background:#b91c1c;color:#fff;cursor:pointer;margin-top:12px;min-height:44px}\nbutton[disabled]{opacity:.5}#msg{font-weight:600}a{color:#c2410c}@media(prefers-color-scheme:dark){body{background:#141210;color:#eee}.box{border-color:#3a3330}}</style></head>\n<body>\n<h1>Delete your HGI Billing account</h1>\n<p>This deletes your HGI Billing account and the business data stored for it in the cloud: company profile, customers, products, invoices,\nquotations, notes, invoice lines and payments. It cannot be undone. Data still on a phone is removed when the app next connects, or when you uninstall it.</p>\n<p>You can also do this in the app: <strong>Settings → Account &amp; sync → Delete account and cloud data</strong>, or e-mail <a href=\"mailto:{{SUPPORT_EMAIL}}\">{{SUPPORT_EMAIL}}</a>.</p>\n<form class=\"box\" id=\"f\" autocomplete=\"off\">\n  <label for=\"u\">Username</label><input type=\"text\" id=\"u\" autocapitalize=\"none\" spellcheck=\"false\" maxlength=\"60\" required>\n  <label for=\"p\">Password</label><input type=\"password\" id=\"p\" maxlength=\"256\" required>\n  <label class=\"chk\"><input type=\"checkbox\" id=\"sure\"> I understand my account and its cloud data will be permanently deleted.</label>\n  <button id=\"go\" type=\"submit\" disabled>Delete my account and cloud data</button>\n  <p id=\"msg\" role=\"status\" aria-live=\"polite\"></p>\n</form>\n<p><a href=\"/privacy\">Privacy policy</a></p>\n<script>\nconst API = \"{{API}}\";\nconst $ = id => document.getElementById(id);\nconst ready = () => { $('go').disabled = !($('u').value.trim() && $('p').value && $('sure').checked); };\n['u', 'p', 'sure'].forEach(id => $(id).addEventListener('input', ready)); $('sure').onchange = ready;\n$('f').onsubmit = async e => {\n  e.preventDefault();\n  $('go').disabled = true; $('msg').textContent = 'Deleting…';\n  try {\n    const body = { username: $('u').value.trim(), password: $('p').value };\n    let status, j;\n    if (API) {   // free server (Google Apps Script): one POST envelope to the web app\n      const r = await fetch(API, { method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' }, body: JSON.stringify({ m: 'POST', p: '/v1/account/delete-with-password', b: body }) });\n      const e = await r.json().catch(() => ({})); status = e.status || r.status; j = e.body || {};\n    } else {\n      const r = await fetch('/v1/account/delete-with-password', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });\n      status = r.status; j = await r.json().catch(() => ({}));\n    }\n    if (status !== 200) throw new Error(j.message || ('HTTP ' + status));\n    $('p').value = ''; $('msg').textContent = 'Done. The account ' + j.username + ' and its cloud data have been deleted.';\n  } catch (err) { $('msg').textContent = 'Could not delete: ' + err.message; ready(); }\n};\n</script>\n</body></html>\n"};

/* HGI Billing — Google Apps Script web app: the same API as the Cloud Run server (backend/lib/router.js), free of charge.
 *
 * Deploy: Execute as "Me" (the spreadsheet owner), access "Anyone". The app sends every call as ONE POST with a text/plain
 * JSON envelope  {m: method, p: path, q: {query}, t: session token, b: body}  (a "simple" request: no CORS pre-flight,
 * which Apps Script cannot answer) and gets back  {status, body}.  GET ?p=/v1/health · ?p=/privacy · ?p=/delete-account.
 *
 * Permission: ONLY https://www.googleapis.com/auth/drive.file — the script can open only spreadsheets it created itself.
 * On its first run it creates its own private spreadsheet (title from Script Property SHEET_TITLE) and keeps its ID.
 * Storage: that spreadsheet, through the Sheets API advanced service, with exactly the storage
 * engine of the Cloud Run server (backend/lib/sheet-db.js …). Apps Script keeps nothing between requests, so every request
 * reads the spreadsheet first; writes run under the script lock (one writer at a time) and are still one atomic
 * spreadsheets.batchUpdate each, checked against _Meta.writeCounter.
 * Secrets (session secret, password pepper) are created on the first request in Script Properties and never leave them;
 * they can be replaced ONCE by the owner-armed import (hgiArmSecretImport) so both servers share them (see docs/FREE-SERVER.md).
 * One server at a time: backend-guard.js (_Meta.activeBackend); switch with hgiActivateAppsScript / hgiActivateCloudRun.
 * Passwords: PBKDF2-HMAC-SHA256 with the pepper (Apps Script has no scrypt); iterations measured once, ~1 s per hash.
 * Not available here: e-invoice / e-way bill (needs RSA encryption), PDF cloud copies, GSTIN look-up.
 */
var HGI_SCHEMA_VERSION = '9.4-1';

function __props() { return PropertiesService.getScriptProperties(); }
